import static org.junit.Assert.assertEquals;

public class Frequency_getCumPct_TriageGen0Test {

    private static final double DELTA = 1e-15;



    @Test
    public void testGetCumPct_SingleValue() {
        Frequency frequency = new Frequency();
        frequency.addValue(10);

        // sumFreq = 1, getCumFreq(10) = 1 -> 1/1 = 1.0
        assertEquals(1.0, frequency.getCumPct(10), DELTA);

        // getCumFreq(5) = 0 (since 5 < 10) -> 0/1 = 0.0
        assertEquals(0.0, frequency.getCumPct(5), DELTA);
    }




}

package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Frequency_getCumPct_TriageGen0Test {

    private static final double DELTA = 1e-15;





    @Test
    public void testGetCumPct_MultipleValues() {
        Frequency frequency = new Frequency();
        frequency.addValue(1); // Freq: 1
        frequency.addValue(3); // Freq: 1
        frequency.addValue(3); // Freq: 2
        frequency.addValue(5); // Freq: 1
        // Total sumFreq = 4

        // Values sorted: 1 (1), 3 (2), 5 (1)

        // CUM Freq for 1: 1 -> 1/4 = 0.25
        assertEquals(0.25, frequency.getCumPct(1), DELTA);

        // CUM Freq for 3: 1 + 2 = 3 -> 3/4 = 0.75
        assertEquals(0.75, frequency.getCumPct(3), DELTA);

        // CUM Freq for 5: 1 + 2 + 1 = 4 -> 4/4 = 1.0
        assertEquals(1.0, frequency.getCumPct(5), DELTA);

        // CUM Freq for value not present but in range (e.g., 4): 
        // getCumFreq(4) should return sum of counts for values <= 4, which is 1+2=3.
        // 3/4 = 0.75
        assertEquals(0.75, frequency.getCumPct(4), DELTA);

        // CUM Freq for value smaller than all: 0/4 = 0.0
        assertEquals(0.0, frequency.getCumPct(0), DELTA);

        // CUM Freq for value larger than all: 4/4 = 1.0
        assertEquals(1.0, frequency.getCumPct(10), DELTA);
    }


}

package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Frequency_getCumPct_TriageGen0Test {

    private static final double DELTA = 1e-15;







    @Test
    public void testGetCumPct_WithStrings() {
        Frequency frequency = new Frequency();
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("cherry");
        // sumFreq = 3

        // "apple" -> 1/3
        assertEquals(1.0/3.0, frequency.getCumPct("apple"), DELTA);
        // "banana" -> 2/3
        assertEquals(2.0/3.0, frequency.getCumPct("banana"), DELTA);
        // "cherry" -> 3/3
        assertEquals(1.0, frequency.getCumPct("cherry"), DELTA);
        // "date" -> 3/3
        assertEquals(1.0, frequency.getCumPct("date"), DELTA);
        // "aardvark" -> 0/3
        assertEquals(0.0, frequency.getCumPct("aardvark"), DELTA);
    }
}
